package com.aistock.prediction.portfolioquestion;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.aistock.prediction.portfolioanalysis.PortfolioRepository;import com.aistock.prediction.explanation.MaasClient;import com.aistock.common.BusinessException;import com.fasterxml.jackson.databind.*;import java.util.*;import java.time.*;import static com.aistock.prediction.portfolioquestion.QuestionEvidence.*;import static com.aistock.prediction.portfolioquestion.PortfolioQuestionRecords.*;
class PortfolioQuestionServiceTest {
 final PortfolioQuestionRepository r=mock(PortfolioQuestionRepository.class);final PortfolioRepository source=mock(PortfolioRepository.class);final Clock clock=Clock.fixed(Instant.parse("2026-10-20T00:00:00Z"),ZoneOffset.UTC);final TextModel client=new TextModel();
 static final class TextModel implements MaasClient {int calls;boolean enabled=true;boolean fail;JsonNode reply;public boolean enabled(){return enabled;}public String model(){return "fixture-model";}public JsonNode generate(Map<String,String> f){throw new AssertionError("Wrong model profile");}public JsonNode generatePortfolioQuestion(String q,Map<String,String> f){calls++;if(fail)throw new IllegalStateException("private provider details");return reply;}}
 PortfolioQuestionService service(boolean enabled){return new PortfolioQuestionService(r,source,client,M,clock,enabled,1800,98304,65536);}
 Request request(boolean consent){return new Request(UUID.randomUUID(),ID,"解释盈亏",consent);}
 Receipt receipt(Request q,String state){return new Receipt(q.operationId(),q.analysisId(),q.question(),state,"SUCCEEDED".equals(state)?UUID.randomUUID():null,"FAILED".equals(state)?"AI_UNAVAILABLE":null,clock.instant().plusSeconds(45));}
 @Test void successfulQuestionUsesOneValidatedCallAndCompletesReceipt(){var q=request(true);when(source.get(OWNER,ID)).thenReturn(saved());when(r.claim(eq(OWNER),eq(q),any(),eq(clock))).thenReturn(new Claim(true,receipt(q,"RUNNING")));var out=M.createObjectNode().put("status","OUT_OF_SCOPE").put("topic","LIMITATION");out.putArray("paragraphs");client.reply=out;var done=receipt(q,"SUCCEEDED");when(r.complete(eq(OWNER),eq(q.operationId()),any(),isNull(),eq(clock))).thenReturn(done);assertEquals(done,service(true).generate(OWNER,q));assertEquals(1,client.calls);}
 @Test void replayAndCachedAnswersNeverCallTheModel(){var q=request(true);var done=receipt(q,"SUCCEEDED");when(r.replay(OWNER,q,clock)).thenReturn(done);assertEquals(done,service(true).generate(OWNER,q));assertEquals(0,client.calls);verifyNoInteractions(source);reset(r);when(source.get(OWNER,ID)).thenReturn(saved());when(r.claim(eq(OWNER),eq(q),any(),eq(clock))).thenReturn(new Claim(false,done));assertEquals(done,service(true).generate(OWNER,q));assertEquals(0,client.calls);}
 @Test void unacknowledgedDisclosureAndUnownedDataStopBeforeCalling(){var q=request(false);when(source.get(OWNER,ID)).thenReturn(saved());assertEquals("AI_DISCLOSURE_REQUIRED",assertThrows(BusinessException.class,()->service(true).generate(OWNER,q)).code());assertEquals(0,client.calls);var other=UUID.randomUUID();when(source.get(other,ID)).thenThrow(new BusinessException("RESOURCE_NOT_FOUND","missing",org.springframework.http.HttpStatus.NOT_FOUND));assertEquals("RESOURCE_NOT_FOUND",assertThrows(BusinessException.class,()->service(true).generate(other,request(true))).code());}
 @Test void closedAiStillAllowsRulesAndAllMissingCannotSend(){when(source.get(OWNER,ID)).thenReturn(saved());assertEquals("RULE",service(false).rules(OWNER,ID,"PROFIT_FORMULA").path("source").asText());assertEquals("AI_NOT_CONFIGURED",assertThrows(BusinessException.class,()->service(false).generate(OWNER,request(true))).code());var empty=saved();empty.put("state","EMPTY").put("positionCount",0).put("valuedCount",0).putNull("totals").putArray("lines");empty.put("freshness","UNKNOWN");when(source.get(OWNER,ID)).thenReturn(empty);assertThrows(BusinessException.class,()->service(true).generate(OWNER,request(true)));assertEquals(0,client.calls);}
 @Test void providerAndMalformedOutputFailuresBecomeSafeReceipts(){for(boolean transport:List.of(true,false)){reset(r);var q=request(true);when(source.get(OWNER,ID)).thenReturn(saved());when(r.claim(eq(OWNER),eq(q),any(),eq(clock))).thenReturn(new Claim(true,receipt(q,"RUNNING")));client.fail=transport;client.reply=M.createObjectNode().put("bad","unverified");when(r.complete(eq(OWNER),eq(q.operationId()),isNull(),anyString(),eq(clock))).thenReturn(receipt(q,"FAILED"));assertEquals("FAILED",service(true).generate(OWNER,q).state());verify(r).complete(eq(OWNER),eq(q.operationId()),isNull(),eq(transport?"AI_UNAVAILABLE":"AI_OUTPUT_INVALID"),eq(clock));}assertEquals(2,client.calls);}
 @Test void storageErrorsNeverLeakRawDatabaseDetails(){when(source.get(OWNER,ID)).thenThrow(new org.springframework.dao.DataAccessResourceFailureException("private sql error"));var e=assertThrows(BusinessException.class,()->service(true).generate(OWNER,request(true)));assertEquals("AI_STORAGE_UNAVAILABLE",e.code());assertFalse(e.getMessage().contains("private"));assertEquals(0,client.calls);}
}
